import React, { useState, useEffect } from 'react';

const ParentForm = ({ parentData, setParentData, setSetores, SGG_TOKEN, tipo }) => {
  const [cnpjError, setCnpjError] = useState('');
  const [loadingSetores, setLoadingSetores] = useState(false);

  const formatCNPJ = (cnpj) => {
    cnpj = cnpj.replace(/\D/g, '');
    if (cnpj.length <= 2) return cnpj;
    if (cnpj.length <= 5) return `${cnpj.slice(0, 2)}.${cnpj.slice(2)}`;
    if (cnpj.length <= 8) return `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5)}`;
    if (cnpj.length <= 12) return `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5, 8)}/${cnpj.slice(8)}`;
    return `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5, 8)}/${cnpj.slice(8, 12)}-${cnpj.slice(12)}`;
  };

  const validarCNPJ = (cnpj) => {
    const regex = /^(?:\d{2}\.\d{3}\.\d{3}\/\d{4}\-\d{2}|\d{14})$/;
    return regex.test(cnpj);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === 'cnpj_empresa') {
      const formattedCNPJ = formatCNPJ(value);
      setParentData(prev => ({ ...prev, [name]: formattedCNPJ }));

      if (!validarCNPJ(formattedCNPJ)) {
        setCnpjError('CNPJ inválido. Por favor, insira no formato correto!');
      } else {
        setCnpjError('');
      }
    } else {
      setParentData(prev => ({ ...prev, [name]: value }));
    }
  };

  useEffect(() => {
    const fetchSetores = async () => {
      if (parentData.cnpj_empresa && validarCNPJ(parentData.cnpj_empresa)) {
        setLoadingSetores(true);
        try {
          const responseEmpresa = await fetch(
            `/api/v3/empresa/?cnpj_cpf=${parentData.cnpj_empresa}`,
            {
              method: 'GET',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Basic ${SGG_TOKEN}`
              },
            }
          );

          if (!responseEmpresa.ok) throw new Error('Falha ao buscar empresa');

          const dataEmpresa = await responseEmpresa.json();
          const empresa = dataEmpresa[0];
          const idEmpresa = empresa?.id_empresa;

          if (!idEmpresa) {
            console.warn('ID da empresa não encontrado');
            setSetores([]);
            return;
          }

          const responseSetores = await fetch(
            `/api/v3/setor/?id_empresa=${idEmpresa}`,
            {
              method: 'GET',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Basic ${SGG_TOKEN}`
              },
            }
          );

          if (!responseSetores.ok) throw new Error('Falha ao buscar setores');

          const dataSetores = await responseSetores.json();
          setSetores(dataSetores || []);

        } catch (error) {
          console.error('Erro ao buscar setores:', error);
          setSetores([]);
        } finally {
          setLoadingSetores(false);
        }
      }
    };

    const timeoutId = setTimeout(() => {
      fetchSetores();
    }, 500); // Debounce to avoid too many requests while typing

    return () => clearTimeout(timeoutId);
  }, [parentData.cnpj_empresa, SGG_TOKEN, setSetores]);

  return (
    <div className={tipo === "colaboradores" ? "parent-form colaboradores" : "parent-form-container"}>
      {tipo !== "colaboradores" && (
        <>
          <h2>Dados da Empresa</h2>

          <div className="form-row">

            <div className="form-group">
              
              <label htmlFor="cnpj_empresa">CNPJ da Empresa</label>
              <input
                type="text"
                id="cnpj_empresa"
                name="cnpj_empresa"
                value={parentData.cnpj_empresa}
                onChange={handleChange}
                required
                maxLength={18}
                className={cnpjError ? 'error-input' : ''}
              />
              {cnpjError && <span className="error-message">{cnpjError}</span>}
            </div>

            <div className="form-group">
              <label htmlFor="email_funcionario">
                Email para disponibilização do KIT
              </label>
              <input
                type="email"
                id="email_funcionario"
                name="email_funcionario"
                value={parentData.email_funcionario}
                onChange={handleChange}
              />
            </div>

          </div>

          {loadingSetores && (
            <p className="loading-text">Carregando setores...</p>
          )}
        </>
      )}
    </div>
  );
};

export default ParentForm;
