import React, { useState, useEffect } from 'react';
import Select from 'react-select';
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const ChildForm = ({
    data,
    index,
    onChange,
    onRemove,
    isCollapsed,
    onToggleCollapse,
    setores,
    SGG_TOKEN,
    fornecedores,
    tipo,
}) => {
    const [cargos, setCargos] = useState([]);
    const [loadingCargos, setLoadingCargos] = useState(false);
    const [cpfError, setCpfError] = useState('');
    const [agenda, setAgenda] = useState([]);
    const [horasDisponiveis, setHorasDisponiveis] = useState([]);
    const [minutosDisponiveis, setMinutosDisponiveis] = useState([]);
    const [formaAtendimento, setFormaAtendimento] = useState("");

    const hoje = new Date().toISOString().split("T")[0];
    // Formata dia da semana para evitar UTC
    const getDiaSemana = (dataString) => {
        const [ano, mes, dia] = dataString.split("-");
        return new Date(ano, mes - 1, dia).getDay();
    };

    // Local helpers for validation/formatting
    const formatCPF = (cpf) => {
        cpf = cpf.replace(/\D/g, '');
        if (cpf.length <= 3) return cpf;
        if (cpf.length <= 6) return `${cpf.slice(0, 3)}.${cpf.slice(3)}`;
        if (cpf.length <= 9) return `${cpf.slice(0, 3)}.${cpf.slice(3, 6)}.${cpf.slice(6)}`;
        return `${cpf.slice(0, 3)}.${cpf.slice(3, 6)}.${cpf.slice(6, 9)}-${cpf.slice(9, 11)}`;
    };

    const validarCPF = (cpf) => {
        cpf = cpf.replace(/\D/g, '');
        if (cpf.length !== 11) return false;
        if (/^(\d)\1{10}$/.test(cpf)) return false;
        let soma = 0;
        let resto;
        for (let i = 0; i < 9; i++) soma += parseInt(cpf.charAt(i)) * (10 - i);
        resto = (soma * 10) % 11;
        if (resto === 10 || resto === 11) resto = 0;
        if (resto !== parseInt(cpf.charAt(9))) return false;
        soma = 0;
        for (let i = 0; i < 10; i++) soma += parseInt(cpf.charAt(i)) * (11 - i);
        resto = (soma * 10) % 11;
        if (resto === 10 || resto === 11) resto = 0;
        if (resto !== parseInt(cpf.charAt(10))) return false;
        return true;
    };

    const diasSemanaMap = {
        Dom: 0,
        Seg: 1,
        Ter: 2,
        Qua: 3,
        Qui: 4,
        Sex: 5,
        Sab: 6
    };
    const parseDate = (dateString) => {
        if (!dateString) return null;
        return new Date(dateString + "T00:00:00");
    };

    const formatDate = (date) => {
        if (!date) return "";
        return date.toISOString().split("T")[0];
    };
    const diasPermitidos = [
        ...new Set(
            agenda?.flatMap(a =>
                a.horarios?.map(h => diasSemanaMap[h.dia_de_semana])
            ) || []
        )
    ];

    const handleDateChange = (e) => {
        const selectedDate = new Date(e.target.value);
        const diaSemana = selectedDate.getDay();

        if (diasPermitidos.length && !diasPermitidos.includes(diaSemana)) {
            alert("Esse fornecedor não atende nesse dia.");
            return;
        }

        handleChange(e);
    };

    const handleChange = (e) => {
        const { name, value } = e.target;

        if (name === 'cpf_do_colaborador') {
            const formattedCPF = formatCPF(value);
            if (!validarCPF(formattedCPF)) {
                setCpfError('CPF inválido');
            } else {
                setCpfError('');
            }
            onChange(index, name, formattedCPF);
        } else {
            onChange(index, name, value);
        }
    };

    const handleSelectChange = (name, selectedOption) => {
        onChange(index, name, selectedOption ? selectedOption.value : '');
    };

    // Fetch cargos when setor changes
    useEffect(() => {
        const fetchCargos = async () => {
            if (data.setor) {
                setLoadingCargos(true);
                try {
                    const response = await fetch(
                        `/api/v3/cargo/?id_setor=${data.setor}`,
                        {
                            method: 'GET',
                            headers: {
                                'Content-Type': 'application/json',
                                'Authorization': `Basic ${SGG_TOKEN}`
                            },
                        }
                    );
                    const result = await response.json();
                    setCargos(result || []);
                } catch (error) {
                    console.error('Erro ao buscar cargos:', error);
                } finally {
                    setLoadingCargos(false);
                }
            } else {
                setCargos([]);
            }
        };

        fetchCargos();
    }, [data.setor, SGG_TOKEN]);

    const fornecedorOptions = Array.isArray(fornecedores) ? fornecedores.map((f) => ({
        value: f.codigoSGG,
        label: f.razaoSocial,
    })) : [];

    useEffect(() => {
        const fetchAgenda = async () => {
            if (!data.fornecedor) {
                setAgenda([]);
                return;
            }

            try {
                const response = await fetch(
                    `/api/v3/agenda/?id_fornecedor=${data.fornecedor}`,
                    {
                        method: 'GET',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Basic ${SGG_TOKEN}`
                        },
                    }
                );

                const result = await response.json();
                setAgenda(result || []);
                if (result?.length) {
                    const forma = result[0].forma_atendimento;
                    setFormaAtendimento(forma);
                    onChange(index, 'forma_de_atendimento', forma);
                }
            } catch (error) {
                console.error('Erro ao buscar agenda:', error);
                setAgenda([]);
            }
        };

        fetchAgenda();
    }, [data.fornecedor]);

    useEffect(() => {
        const fetchHorarios = async () => {
            if (
                !data.data_para_realiza_o_do_agendamento ||
                formaAtendimento !== "Hora" ||
                !agenda.length
            ) {
                setHorasDisponiveis([]);
                setMinutosDisponiveis([]);
                return;
            }

            try {
                const agendaNome = agenda[0].nome;

                const response = await fetch(`/api/v3/agendamento/`, {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                    },
                    body: JSON.stringify({
                        agenda: agendaNome,
                        data_inicio: data.data_para_realiza_o_do_agendamento,
                        data_fim: data.data_para_realiza_o_do_agendamento
                    })
                });

                const result = await response.json();

                const horas = [...new Set(result.map(r => r.hora_agendamento.split(":")[0]))];
                const minutos = [...new Set(result.map(r => r.hora_agendamento.split(":")[1]))];


                setHorasDisponiveis(horas);
                setMinutosDisponiveis(minutos);

            } catch (error) {
                console.error("Erro ao buscar horários:", error);
            }
        };

        fetchHorarios();
    }, [data.data_para_realiza_o_do_agendamento, formaAtendimento, agenda]);

    useEffect(() => {
        if (
            formaAtendimento !== "Chegada" ||
            !data.data_para_realiza_o_do_agendamento ||
            !agenda.length
        ) return;

        const diaSemana = getDiaSemana(data.data_para_realiza_o_do_agendamento);

        const horariosDia = agenda[0].horarios.filter(
            h => diasSemanaMap[h.dia_de_semana] === diaSemana
        );

        const horas = [];

        horariosDia.forEach(h => {
            const horaInicio = parseInt(h.inicio.split(":")[0]);
            const horaFim = parseInt(h.fim.split(":")[0]);

            for (let i = horaInicio; i < horaFim; i++) {
                horas.push(String(i).padStart(2, "0"));
            }
        });

        setHorasDisponiveis([...new Set(horas)]);
        setMinutosDisponiveis([]);

    }, [data.data_para_realiza_o_do_agendamento, formaAtendimento]);

    const validateForm = () => {
        const requiredFields = [
            'tipo_do_exame',
            'nome_completo',
            'cpf_do_colaborador',
            'data_para_realiza_o_do_agendamento',
            'fornecedor'
        ];

        for (const field of requiredFields) {
            if (!data[field]) return false;
        }

        if (data.tipo_do_exame === 'Admissional') {
            const admissionalFields = [
                'o_colaborador_candidato_ou_ativo',
                'sexo_do_colaborador',
                'data_de_nascimento',
                'data_de_admiss_o',
                'setor',
                'cargo'
            ];
            for (const field of admissionalFields) {
                if (!data[field]) return false;
            }
        }

        if (data.tipo_do_exame === 'Demissional') {
            if (!data.data_de_desligamento) return false;
        }

        if (data.tipo_do_exame === 'Mudança de Função') {
            const changeFields = [
                'data_da_mudan_a_de_fun_o',
                'setor',
                'cargo',
                'houve_mudan_a_de_riscos'
            ];
            for (const field of changeFields) {
                if (!data[field]) return false;
            }
        }

        return true;
    };

    const handleCollapse = () => {
        if (validateForm()) {
            onToggleCollapse();
        } else {
            alert('Por favor, preencha todos os campos obrigatórios antes de concluir o agendamento.');
        }
    };

    if (isCollapsed) {
        return (
            <div className="child-form-collapsed" onClick={onToggleCollapse}>
                <div className="collapsed-header">
                    <span className="collapsed-title">
                        {data.nome_completo || `Colaborador ${index + 1}`}
                    </span>
                    <span className="collapsed-subtitle">
                        {data.tipo_do_exame || 'Tipo de exame não selecionado'}
                    </span>
                </div>
                <button className="expand-btn" type="button">Editar</button>
            </div>
        );
    }

    return (
        <div className="child-form-container">
            {tipo !== "colaboradores" && (
                <div className="child-form-header">
                    <h3>Agendamento {index > 1 ? index + 1 : ''}</h3>
                    {index > 0 && (
                        <button type="button" className="remove-btn" onClick={() => onRemove(index)}>
                            Remover
                        </button>
                    )}
                </div>
            )}

            <div className="form-grid">
                <div className="form-group full-width">
                    <label htmlFor={`tipo_do_exame_${index}`}>Tipo do Exame</label>
                    <select
                        id={`tipo_do_exame_${index}`}
                        name="tipo_do_exame"
                        value={data.tipo_do_exame}
                        onChange={handleChange}
                        required
                    >
                        {tipo === "colaboradores" ? (
                            <>
                                <option value="">Selecione</option>
                                <option value="Admissional">Admissional</option>
                                <option value="Demissional">Demissional</option>
                                <option value="Periódico">Periódico</option>
                            </>
                        ) : (
                            <>
                                <option value="">Selecione</option>
                                <option value="Admissional">Admissional</option>
                                <option value="Periódico">Periódico</option>
                                <option value="Demissional">Demissional</option>
                                <option value="Retorno ao trabalho">Retorno ao trabalho</option>
                                <option value="Mudança de função">Mudança de função</option>
                            </>
                        )}
                    </select>
                </div>

                <div className="form-group">
                    <label htmlFor={`nome_completo_${index}`}>Nome do Colaborador</label>
                    <input
                        type="text"
                        id={`nome_completo_${index}`}
                        name="nome_completo"
                        value={data.nome_completo}
                        onChange={handleChange}
                        required
                    />
                </div>

                <div className="form-group">
                    <label htmlFor={`cpf_do_colaborador_${index}`}>CPF do Colaborador</label>
                    <input
                        type="text"
                        id={`cpf_do_colaborador_${index}`}
                        name="cpf_do_colaborador"
                        value={data.cpf_do_colaborador}
                        onChange={handleChange}
                        required
                        className={cpfError ? 'error-input' : ''}
                    />
                    {cpfError && <span className="error-message">{cpfError}</span>}
                </div>

                {/* Conditional Fields based on Exam Type */}
                {tipo !== "colaboradores" && data.tipo_do_exame === "Admissional" && (
                    <>
                        <div className="form-group">
                            <label>Candidato ou Ativo?</label>
                            <select
                                name="o_colaborador_candidato_ou_ativo"
                                value={data.o_colaborador_candidato_ou_ativo}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione...</option>
                                <option value="Candidato">Candidato</option>
                                <option value="Ativo">Ativo</option>
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Sexo</label>
                            <select
                                name="sexo_do_colaborador"
                                value={data.sexo_do_colaborador}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione...</option>
                                <option value="M">Masculino</option>
                                <option value="F">Feminino</option>
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Data de Nascimento</label>
                            <input
                                type="date"
                                name="data_de_nascimento"
                                value={data.data_de_nascimento}
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className="form-group">
                            <label>Data de Admissão</label>
                            <input
                                type="date"
                                name="data_de_admiss_o"
                                value={data.data_de_admiss_o}
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className="form-group">
                            <label>Setor</label>
                            <select
                                name="setor"
                                value={data.setor}
                                onChange={handleChange}
                                required
                                disabled={!setores.length}
                            >
                                <option value="">Selecione...</option>
                                {setores.map((s) => (
                                    <option key={s.id_setor} value={s.id_setor}>{s.setor}</option>
                                ))}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Cargo</label>
                            <select
                                name="cargo"
                                value={data.cargo}
                                onChange={handleChange}
                                required
                                disabled={loadingCargos || !cargos.length}
                            >
                                <option value="">Selecione...</option>
                                {cargos.map((c) => (
                                    <option key={c.id_cargo} value={c.id_cargo}>{c.cargo}</option>
                                ))}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Telefone</label>
                            <input
                                type="tel"
                                name="telefone"
                                value={data.telefone}
                                onChange={handleChange}
                                required
                                disabled={loadingCargos || !cargos.length}
                            />
                        </div>
                        <div className="form-group max-width">
                            <label>Email</label>
                            <input
                                type="email"
                                name="email"
                                value={data.email}
                                onChange={handleChange}
                                required
                                disabled={loadingCargos || !cargos.length}
                            />
                        </div>
                    </>
                )}

                {tipo !== "colaboradores" && data.tipo_do_exame === "Demissional" && (
                    <div className="form-group">
                        <label>Data de Desligamento</label>
                        <input
                            type="date"
                            name="data_de_desligamento"
                            value={data.data_de_desligamento}
                            onChange={handleChange}
                            required
                        />
                    </div>
                )}

                {tipo !== "colaboradores" && data.tipo_do_exame === "Mudança de Função" && (
                    <>
                        <div className="form-group">
                            <label>Data da Mudança</label>
                            <input
                                type="date"
                                name="data_da_mudan_a_de_fun_o"
                                value={data.data_da_mudan_a_de_fun_o}
                                onChange={handleChange}
                                required
                            />
                        </div>
                        <div className="form-group">
                            <label>Novo Setor</label>
                            <select
                                name="setor"
                                value={data.setor}
                                onChange={handleChange}
                                required
                                disabled={!setores.length}
                            >
                                <option value="">Selecione...</option>
                                {setores.map((s) => (
                                    <option key={s.id_setor} value={s.id_setor}>{s.setor}</option>
                                ))}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Novo Cargo</label>
                            <select
                                name="cargo"
                                value={data.cargo}
                                onChange={handleChange}
                                required
                                disabled={loadingCargos || !cargos.length}
                            >
                                <option value="">Selecione...</option>
                                {cargos.map((c) => (
                                    <option key={c.id_cargo} value={c.id_cargo}>{c.cargo}</option>
                                ))}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Houve Mudança de Riscos?</label>
                            <select
                                name="houve_mudan_a_de_riscos"
                                value={data.houve_mudan_a_de_riscos}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione...</option>
                                <option value="Sim">Sim</option>
                                <option value="Não">Não</option>
                            </select>
                        </div>
                    </>
                )}

                <div className="form-group full-width">
                    <label>Unidade de Atendimento</label>
                    <Select
                        options={fornecedorOptions}
                        value={fornecedorOptions.find(option => option.value === data.fornecedor)}
                        onChange={(option) => handleSelectChange('fornecedor', option)}
                        placeholder="Selecione ou pesquise..."
                        isSearchable
                        required
                    />
                </div>

                {data.fornecedor && (
                    <>
                        <div className="form-group">
                            <label>Data Desejada para Realização do Agendamento</label>

                            <DatePicker
                                selected={parseDate(data.data_para_realiza_o_do_agendamento)}
                                onChange={(date) => {
                                    if (!date) return;

                                    const diaSemana = date.getDay();

                                    if (!diasPermitidos.length) {
                                        alert("Fornecedor sem agenda disponível.");
                                        return;
                                    }

                                    if (!diasPermitidos.includes(diaSemana)) {
                                        alert("Esse fornecedor não atende nesse dia.");
                                        return;
                                    }

                                    onChange(
                                        index,
                                        "data_para_realiza_o_do_agendamento",
                                        formatDate(date)
                                    );
                                }}
                                filterDate={(date) => {
                                    const dia = date.getDay();

                                    // bloqueia datas passadas
                                    const hojeDate = new Date();
                                    hojeDate.setHours(0, 0, 0, 0);

                                    if (date < hojeDate) return false;

                                    // bloqueia se não tiver agenda
                                    if (!diasPermitidos.length) return false;

                                    // 🔥 aqui é o principal
                                    return diasPermitidos.includes(dia);
                                }}
                                dateFormat="dd/MM/yyyy"
                                placeholderText="Selecione uma data"
                                className="input"
                            />

                        </div>
                        {formaAtendimento === "Hora" && data.data_para_realiza_o_do_agendamento && (
                            <div className='form-group'>
                                <br></br>
                                <span className='forma-atendimento-warning'>Clínica selecionada apenas sob agendamento</span>
                            </div>
                        )}
                    </>
                )}

                {formaAtendimento === "Hora" && data.data_para_realiza_o_do_agendamento && (
                    <>
                        <div className='full-width'>
                            <label>Como a clínica selecionada funciona por agendamento, precisamos confirmar diretamente com eles. Por isso, pedimos que selecione 3 horários disponíveis, na ordem de preferência, para que possamos confirmar com a clínica.</label>
                        </div>
                        <div className='form-group full-width'>
                            <label className='full-width'>Selecione o primeiro horário para verificarmos disponibilidade</label>
                        </div>
                        <div className="form-group">

                            <label>Hora</label>
                            <select
                                name="hora_agendamento"
                                value={data.hora_agendamento || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {horasDisponiveis.map((h, i) => (
                                    <option key={i} value={h}>{h}</option>
                                ))}
                            </select>
                        </div>

                        <div className="form-group">
                            <label>Minuto</label>
                            <select
                                name="minuto_agendamento"
                                value={data.minuto_agendamento || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {minutosDisponiveis.map((m, i) => (
                                    <option key={i} value={m}>{m}</option>
                                ))}
                            </select>
                        </div>
                        <div className="form-group full-width">
                            <label>Selecione o segundo horário para verificarmos disponibilidade</label>
                        </div>
                        <div className="form-group">
                            <label>Hora</label>
                            <select
                                name="hora_agendamento2"
                                value={data.hora_agendamento2 || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {horasDisponiveis.map((h, i) => (
                                    <option key={i} value={h}>{h}</option>
                                ))}
                            </select>
                        </div>

                        <div className="form-group">
                            <label>Minuto</label>
                            <select
                                name="minuto_agendamento2"
                                value={data.minuto_agendamento2 || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {minutosDisponiveis.map((m, i) => (
                                    <option key={i} value={m}>{m}</option>
                                ))}
                            </select>
                        </div>

                        <div className="form-group full-width">
                            <label>Selecione o terceiro horário para verificarmos disponibilidade</label>
                        </div>
                        <div className="form-group">
                            <label>Hora</label>
                            <select
                                name="hora_agendamento3"
                                value={data.hora_agendamento3 || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {horasDisponiveis.map((h, i) => (
                                    <option key={i} value={h}>{h}</option>
                                ))}
                            </select>
                        </div>

                        <div className="form-group">
                            <label>Minuto</label>
                            <select
                                name="minuto_agendamento3"
                                value={data.minuto_agendamento3 || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {minutosDisponiveis.map((m, i) => (
                                    <option key={i} value={m}>{m}</option>
                                ))}
                            </select>
                        </div>
                    </>
                )}

                {formaAtendimento === "Chegada" && data.data_para_realiza_o_do_agendamento && (
                    <>
                        <div className="form-group">
                            <label>Hora de Chegada</label>
                            <select
                                name="hora_agendamento"
                                value={data.hora_agendamento || ""}
                                onChange={handleChange}
                                required
                            >
                                <option value="">Selecione</option>
                                {horasDisponiveis.map((h, i) => (
                                    <option key={i} value={h}>{h}</option>
                                ))}
                            </select>
                        </div>

                        <div className="form-group">
                            <small style={{ color: "#666" }}>
                                Atendimento por ordem de chegada dentro do horário selecionado.
                            </small>
                        </div>
                    </>
                )}

                <div className="form-group full-width">
                    <label>Observações</label>
                    <input
                        type="text"
                        name="observacoes"
                        value={data.observacoes}
                        onChange={handleChange}
                    />
                </div>

                {tipo === "colaboradores" && (
                    <div className="form-group full-width">
                        <label htmlFor="email_funcionario">
                            Email para disponibilização do KIT
                        </label>

                        <input
                            type="email"
                            id="email_funcionario"
                            name="email_funcionario"
                            value={data.email_funcionario}
                            onChange={handleChange}
                        />
                    </div>
                )}

            </div>
            {tipo !== "colaboradores" && (
                <div className="child-footer">
                    <button type="button" className="collapse-btn" onClick={handleCollapse}>
                        Concluir este agendamento
                    </button>
                </div>
            )}
        </div>
    );
};

export default ChildForm;
