import React, { useState, useEffect } from 'react';
import '../App.css';
import ParentForm from '../components/ParentForm';
import ChildForm from '../components/ChildForm';

const PIPEFY_TOKEN = process.env.PIPEFY_TOKEN;
const SGG_TOKEN = process.env.USER_SGG;

function SolicitacaoExames({ tipo }) {
    const titulo = tipo === "colaboradores"
        ? "Solicitação de Exames - Colaboradores"
        : "Solicitação de Exames";

    const [parentData, setParentData] = useState({
        cnpj_empresa: '',
        email_funcionario: '',
    });

    const [exams, setExams] = useState([]);
    const [setores, setSetores] = useState([]);
    const [fornecedores, setFornecedores] = useState([]);
    const [globalError, setGlobalError] = useState('');
    const [successMessage, setSuccessMessage] = useState('');
    const [isSuccessVisible, setIsSuccessVisible] = useState(false); // Control visibility of success message
    const [isProcessing, setIsProcessing] = useState(false); // Control if the form is processing


    // Fetch fornecedores once
    useEffect(() => {
        const fetchFornecedores = async () => {
            try {
                const response = await fetch('/api/v3/fornecedores', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                });
                if (!response.ok) throw new Error('Erro ao buscar fornecedores');
                const data = await response.json();
                setFornecedores(data || []);
            } catch (error) {
                console.error('Erro ao carregar fornecedores:', error);
            }
        };
        fetchFornecedores();
    }, []);

    const resetForm = () => {
        setParentData({
            cnpj_empresa: '',
            email_funcionario: '',
        });

        setExams([emptyExam()]);
    };

    const emptyExam = () => ({
        id: Date.now(),
        tipo_do_exame: '',
        nome_completo: '',
        cpf_do_colaborador: '',
        data_para_realiza_o_do_agendamento: '',
        o_colaborador_candidato_ou_ativo: '',
        sexo_do_colaborador: '',
        data_de_nascimento: '',
        setor: '',
        cargo: '',
        data_de_admiss_o: '',
        data_de_desligamento: '',
        data_da_mudan_a_de_fun_o: '',
        novo_setor: '',
        novo_cargo: '',
        houve_mudan_a_de_riscos: '',
        fornecedor: '',
        observacoes: '',
        isCollapsed: false
    });

    const addExam = () => {

        // colaboradores só pode ter 1 exame
        if (tipo === "colaboradores" && exams.length >= 1) {
            alert("Para a colaboradores é permitido apenas um agendamento.");
            return;
        }

        setExams([
            ...exams,
            {
                id: Date.now(),
                tipo_do_exame: '',
                nome_completo: '',
                cpf_do_colaborador: '',
                data_para_realiza_o_do_agendamento: '',
                o_colaborador_candidato_ou_ativo: '',
                sexo_do_colaborador: '',
                data_de_nascimento: '',
                setor: '',
                cargo: '',
                data_de_admiss_o: '',
                data_de_desligamento: '',
                data_da_mudan_a_de_fun_o: '',
                novo_setor: '',
                novo_cargo: '',
                houve_mudan_a_de_riscos: '',
                fornecedor: '',
                observacoes: '',
                forma_de_atendimento: '',
                isCollapsed: false,
            }
        ]);
    };

    const removeExam = (index) => {
        const newExams = [...exams];
        newExams.splice(index, 1);
        setExams(newExams);
    };

    const updateExam = (index, field, value) => {
        const newExams = [...exams];
        newExams[index][field] = value;
        setExams(newExams);
    };

    const toggleCollapse = (index) => {
        const newExams = [...exams];
        newExams[index].isCollapsed = !newExams[index].isCollapsed;
        setExams(newExams);
    };

    // Initialize with one empty exam if none exist
    useEffect(() => {
        if (exams.length === 0) {
            setExams([emptyExam()]);
        }
    }, []);

    const handleSubmitAll = async () => {
        if (!parentData.cnpj_empresa && tipo !== "colaboradores") {
            alert('CNPJ da empresa é obrigatório.');
            return;
        }

        // Basic validation for all exams
        for (let i = 0; i < exams.length; i++) {
            const exam = exams[i];
            if (!exam.nome_completo || !exam.cpf_do_colaborador || !exam.tipo_do_exame || !exam.fornecedor) {
                alert(tipo !== "colaboradores" ? `Preencha os campos obrigatórios do agendamento ${i + 1} (Nome, CPF, Tipo, Fornecedor). :` : `Preencha os campos obrigatórios do agendamento: (Nome, CPF, Tipo, Fornecedor).`);
                return;
            }
        }

        setGlobalError('');
        setSuccessMessage('')
        setIsSuccessVisible(false);
        setIsProcessing(true); // Start processing

        const promises = exams.map(exam => {
            const fornecedor = fornecedores.find(f => f.codigoSGG === exam.fornecedor);

            // Pegando o nome do fornecedor (razão social)
            const fornecedor_nome = fornecedor ? fornecedor.razaoSocial : '';
            const payload = {
                ...exam,
                tipoAgendamento: tipo,
                forma_de_atendimento: exam.forma_de_atendimento || "",
                fornecedor_nome: fornecedor_nome,
                cnpj_empresa: parentData.cnpj_empresa,
                email_funcionario: parentData.email_funcionario ? parentData.email_funcionario : exam.email_funcionario,
            };
            console.log(payload);
            // Clean up internal flags
            delete payload.id;
            delete payload.isCollapsed;

            return fetch('/api/v3/submit-form/', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            }).then(async res => {
                if (!res.ok) {
                    const err = await res.json();
                    throw new Error(err.error || `Erro no agendamento de ${exam.nome_completo}`);
                }
                return res.json();
            });
        });

        try {
            await Promise.all(promises);
            setSuccessMessage(tipo === "colaboradores" ? "Agendamento solicitado com sucesso!" : "Solicitações enviadas com sucesso!");
            setIsSuccessVisible(true); // Show success message
            resetForm(); // 👈 reseta TUDO
        } catch (error) {
            console.error('Erro no envio em massa:', error);
            setGlobalError(`Ocorreu um erro ao enviar alguns agendamentos: ${error.message}`);
        } finally {
            setIsProcessing(false); // Stop processing
        }
    };

    const handleOkClick = () => {
        resetForm();
        setSuccessMessage('');
        setIsSuccessVisible(false); // Hide the success message and reset form
    };

    return (
        <div className={`App ${tipo === "colaboradores" ? "colaboradores-theme" : ""}`}>
            <header className={`${tipo === "colaboradores" ? "app-header-colaboradores" : "app-header"}`}>
                <img src='LOGO.png' className='header-img' />
                <h1>{titulo}</h1>
            </header>

            <main className="app-content">
                {/* Show success message or loading, otherwise show form */}
                {isSuccessVisible ? (
                    <div className="parent-form-container">
                        <h2>{successMessage}</h2>
                        <div className="actions-bar">
                            <button onClick={handleOkClick} className="btn-primary">
                                OK
                            </button>
                        </div>
                    </div>
                ) : isProcessing ? (
                    <div className="parent-form colaboradores">
                        Processando, aguarde...
                    </div>
                ) : (
                    <>
                        <ParentForm
                            parentData={parentData}
                            setParentData={setParentData}
                            setSetores={setSetores}
                            SGG_TOKEN={SGG_TOKEN}
                            tipo={tipo}
                        />

                        <div className="exams-list">
                            {exams.map((exam, index) => (
                                <ChildForm
                                    key={exam.id}
                                    index={index}
                                    data={exam}
                                    onChange={updateExam}
                                    onRemove={removeExam}
                                    isCollapsed={exam.isCollapsed}
                                    onToggleCollapse={() => toggleCollapse(index)}
                                    setores={setores}
                                    SGG_TOKEN={SGG_TOKEN}
                                    fornecedores={fornecedores}
                                    tipo={tipo}
                                />
                            ))}
                        </div>

                        <div className="actions-bar">
                            {tipo !== "colaboradores" && (
                                <button className="btn-secondary" onClick={addExam}>
                                    + Agendar novo exame
                                </button>
                            )}

                            <button className="btn-primary" onClick={handleSubmitAll}>
                                {tipo === "colaboradores" ? "Solicitar Agendamento" : "Enviar Solicitações"}
                            </button>
                        </div>

                        {globalError && <div className="error-banner">{globalError}</div>}
                    </>
                )}
            </main>
        </div>
    );
}

export default SolicitacaoExames;